  for _ in range(n):
    ds.append(sum(random.choices(yb,k=len(yb)))/len(yb)-sum(random.choices(ya,k=len(ya)))/len(ya))
  ds.sort();return ds[50],ds[1950]
ex=lambda w:[r for r in S if wk(r['timestamp'])==w and r['landing_page']!='/lp/summer-sale']
print('CI ex-summer wk2-wk1 ckout rate',boot(ex(1),ex(2)))
